// Package filecomplexity is simple everywhere and complex in total.
package filecomplexity // want `file has a total complexity of [0-9]+, limit is 40`

// Fn0 is individually simple.
func Fn0(n int) int {
	if n > 0 {
		n++
	}

	if n > 1 {
		n++
	}

	if n > 2 {
		n++
	}

	return n
}

